397	<body>
398	  <main>
399	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
400	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
401	        <circle cx="200" cy="200" r="200"/>
402	      </svg>
403	    </button>
404	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
405	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
406	    <div class="controls" role="group" aria-label="Circle controls">
407	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
408	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
409	    </div>
410	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
411	  </main>
412	
413	  <script defer>
414	    (() => {
415	      const CONFIG = {
416	        storageKey: 'circle-state',
417	        tapDelay: 300,
418	        colorShiftDuration: 500,
419	        colorModes: [
420	          { class: 'default', name: 'Default White' },
421	          { class: 'color-mode-1', name: 'Pink' },
422	          { class: 'color-mode-2', name: 'Teal' },
423	          { class: 'color-mode-3', name: 'Mint' },
424	          { class: 'color-mode-4', name: 'Purple' },
425	          { class: 'color-mode-5', name: 'Orange' }
426	        ],
427	        isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0
428	      };
429	
430	      const el = {
431	        circle: document.getElementById('decorative-circle'),
432	        hint: document.getElementById('hint-text'),
433	        modeIndicator: document.getElementById('mode-indicator'),
434	        cycleBtn: document.getElementById('cycle-btn'),
435	        resetBtn: document.getElementById('reset-btn')
436	      };
437	
438	      let state = { active: false, colorMode: 0 };
439	      let tapCount = 0;
440	      let tapTimeout = null;
441	      let animatingColorShift = false;
442	
443	      const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
444	      const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
445	
446	      const storage = {
447	        save() {
448	          try {
449	            localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
450	          } catch {
451	            // Silently fail if localStorage is unavailable or quota exceeded
452	          }
453	        },
454	        load() {
455	          try {
456	            const saved = localStorage.getItem(CONFIG.storageKey);
457	            if (saved) {
458	              const parsed = JSON.parse(saved);
459	              if (parsed && typeof parsed === 'object') {
460	                state = { ...state, ...parsed };
461	              }
462	            }
463	          } catch {
464	            // Silently fail if parsing fails
465	          }
466	        }
467	      };
468	
469	      const updateClasses = () => {
470	        const colorClasses = CONFIG.colorModes.map(m => m.class);
471	        el.circle.classList.remove('active', ...colorClasses);
472	        el.circle.setAttribute('aria-pressed', state.active);
473	        if (state.active) el.circle.classList.add('active');
474	        if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
475	      };
476	
477	      const updateUI = () => {
478	        let hintText = '';
479	
480	        if (CONFIG.isTouch) {
481	          hintText = state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle';
482	        } else {
483	          hintText = state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle';
484	        }
485	
486	        el.hint.textContent = hintText;
487	
488	        const showMode = state.active && state.colorMode > 0;
489	        el.modeIndicator.classList.toggle('visible', showMode);
490	        if (showMode) {
491	          const modeName = getColorModeName(state.colorMode);
492	          el.modeIndicator.textContent = `◆ ${modeName.toUpperCase()}`;
493	        }
494	      };
495	
496	      const applyState = () => {
497	        updateClasses();
498	        updateUI();
499	      };
500	
501	      const toggleActive = () => {
502	        state.active = !state.active;
503	        applyState();
504	        storage.save();
505	      };
506	
507	      const cycleColor = () => {
508	        if (animatingColorShift) return;
509	        animatingColorShift = true;
510	        state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
511	        state.active = true;
512	        el.circle.classList.add('color-shifting');
513	        setTimeout(() => {
514	          el.circle.classList.remove('color-shifting');
515	          animatingColorShift = false;
516	        }, CONFIG.colorShiftDuration);
517	        applyState();
518	        storage.save();
519	      };
520	
521	      const resetState = () => {
522	        state = { active: false, colorMode: 0 };
523	        applyState();
524	        storage.save();
525	      };
526	
527	      const handleClick = () => {
528	        if (!CONFIG.isTouch) toggleActive();
529	      };
530	
531	      const handleDblClick = () => {
532	        cycleColor();
533	      };
534	
535	      const handleTouchEnd = () => {
536	        tapCount++;
537	        clearTimeout(tapTimeout);
538	        if (tapCount === 1) {
539	          tapTimeout = setTimeout(() => {
540	            if (tapCount === 1) toggleActive();
541	            tapCount = 0;
542	          }, CONFIG.tapDelay);
543	        } else if (tapCount === 2) {
544	          cycleColor();
545	          tapCount = 0;
546	        }
547	      };
548	
549	      const keyHandlers = {
550	        ' ': toggleActive,
551	        'enter': toggleActive,
552	        'c': cycleColor,
553	        'r': resetState
554	      };
555	
556	      const handleKeyDown = (e) => {
557	        const handler = keyHandlers[e.key.toLowerCase()];
558	        if (handler) {
559	          e.preventDefault();
560	          handler();
561	        }
562	      };
563	
564	      const initListeners = () => {
565	        if (CONFIG.isTouch) {
566	          el.circle.addEventListener('touchend', handleTouchEnd);
567	        } else {
568	          el.circle.addEventListener('click', handleClick);
569	          el.circle.addEventListener('dblclick', handleDblClick);
570	        }
571	        el.circle.addEventListener('blur', () => {
572	          tapCount = 0;
573	          clearTimeout(tapTimeout);
574	        });
575	        document.addEventListener('keydown', handleKeyDown);
576	        el.cycleBtn.addEventListener('click', cycleColor);
577	        el.resetBtn.addEventListener('click', resetState);
578	      };
579	
580	      const initApp = () => {
581	        storage.load();
582	        applyState();
583	        initListeners();
584	        el.circle.focus();
585	      };
586	
587	      if (document.readyState === 'loading') {
588	        document.addEventListener('DOMContentLoaded', initApp);
589	      } else {
590	        initApp();
591	      }
592	    })();
593	  </script>
594	</body>
595	</html>
